const e = $json || {};
let taskId = '';
try { taskId = $('When Called').first().json.clickup_task_id || ''; } catch (err) {}
const statusCode = (e.error && (e.error.httpCode || e.error.status || e.error.code)) || e.statusCode || '';
const msg = (e.error && (e.error.message || e.error)) || e.message || 'access_denied';
return [{ json: {
  block: { type: 'text', order: -1, md: '[BRAK: dostep_odmowiony zadanie ' + taskId + ' poza zakresem uprawnien uzytkownika]' },
  clickup_task_id: taskId,
  needs_alert: true,
  has_embedded: false,
  warn_source: 'clickup-asU/access-denied',
  err: ('HTTP ' + statusCode + ' ' + String(msg)).slice(0, 300)
} }];

const src = $input.first().json;
const taskId = src.id || src.clickup_task_id || src.taskId || null;
const atts = Array.isArray(src.attachments) ? src.attachments : [];
let onlyAttId = '';
try { onlyAttId = String(($('When Called').first().json || {}).only_att_id || '').trim(); } catch (e) {}
let onlyBaseId = onlyAttId, onlyInnerIndex = null;
const _m = onlyAttId.match(/^(.+):(\d+)$/);
if (_m) { onlyBaseId = _m[1]; onlyInnerIndex = Number(_m[2]); }
const out = [];
let i = 0;
for (const a of atts) {
  const thisId = String(a.att_id || a.id || '');
  if (onlyAttId && thisId !== onlyBaseId) { i++; continue; }
  const title = a.title || '';
  const ext = String(a.ext || a.extension || title.split('.').pop() || '').toLowerCase();
  out.push({ json: {
    clickup_task_id: taskId,
    att_id: a.att_id || a.id || null,
    title: title || ('attachment.' + ext),
    ext,
    mime: String(a.mime || a.mimetype || '').toLowerCase(),
    url: a.url || a.url_w_query || '',
    order: (a.order !== undefined && a.order !== null ? a.order : i),
    only_inner_index: onlyInnerIndex
  }});
  i++;
}
if (out.length === 0) {
  // No attachments: emit a single passthrough sentinel so the chain still
  // reaches Aggregate Blocks. A zero-item Explode would skip every downstream
  // node, return nothing, and silently null the whole pipeline (no reply/status/cost).
  out.push({ json: { clickup_task_id: taskId, _passthrough: true, order: -1 } });
}
return out;

const m = $json;
if (m._passthrough) {
  // No-attachment passthrough: emit a block-less item so Aggregate Blocks runs
  // (its filter drops items without a `block`) and returns { blocks: [], ... }.
  return { json: { clickup_task_id: m.clickup_task_id } };
}
const hasRef = !!m.url;
const block = hasRef
  ? { type: 'image', order: m.order, ref: m.url, mime: m.mime || 'image/*', source: 'input', source_ref: m.att_id, alt: m.title }
  : { type: 'text', order: m.order, md: '[BRAK: image_ref_missing ' + m.title + ']' };
return { json: {
  block,
  clickup_task_id: m.clickup_task_id,
  title: m.title,
  needs_alert: !hasRef,
  has_embedded: false,
  warn_source: hasRef ? '' : 'multimodal/image-ref-missing',
  err: hasRef ? '' : 'image attachment missing url'
} };

let meta;
try { meta = $('Fan Manifest').item.json; } catch (e) { try { meta = $('Explode Attachments').item.json; } catch (e2) { meta = {}; } }
if (!meta || meta.order === undefined) { meta = { order: 0, title: (meta && meta.title) || 'unknown', clickup_task_id: (meta && meta.clickup_task_id) || null }; }
const doc = ($json && $json.document) || {};
const md = doc.md_content || '';
const ok = !!md;
let err = '';
if (!ok) {
  if ($json && $json.error) { err = $json.error.message || (typeof $json.error === 'string' ? $json.error : JSON.stringify($json.error)); }
  else if ($json && $json.status && $json.status !== 'success') { err = 'docling status=' + $json.status; }
  else { err = 'no md_content'; }
}
const block = ok
  ? { type: 'text', order: meta.order, md }
  : { type: 'text', order: meta.order, md: '[BRAK: extraction_failed ' + meta.title + ']' };
return { json: {
  block,
  clickup_task_id: meta.clickup_task_id,
  title: meta.title,
  needs_alert: !ok,
  has_embedded: ok && (md.includes('<!-- image -->') || md.includes('<!-- missing-image -->')),
  warn_source: !ok ? 'multimodal/extraction-failed' : '',
  err: err || ''
} };

const rows = $input.all().map(i => i.json).filter(j => j && j.block);
const blocks = rows.map(j => j.block).sort((a, b) => (a.order || 0) - (b.order || 0));
const warnings = [];
for (const j of rows) {
  if (j.needs_alert) warnings.push({ source: j.warn_source || 'multimodal/extraction-failed', title: j.title, err: j.err || 'unknown' });
  else if (j.has_embedded) warnings.push({ source: 'multimodal/embedded-image-skipped', title: j.title });
}
let taskId = null;
try { taskId = $('When Called').first().json.clickup_task_id; } catch (e) {}
if (!taskId) { try { taskId = $('Form Trigger').first().json.taskId; } catch (e) {} }
if (!taskId) { const f = rows.find(j => j.clickup_task_id); taskId = f ? f.clickup_task_id : null; }
return [{ json: { blocks, clickup_task_id: taskId, warnings } }];

const m = $json;
const ok = !!m.stored && !!m.ref;
const block = ok
  ? { type: 'image', order: m.order, ref: m.ref, mime: m.mime || 'image/*', source: 'input', source_ref: m.att_id, alt: m.title }
  : { type: 'text', order: m.order, md: '[BRAK: zip_image_store_failed ' + (m.title || '') + ']' };
return { json: { block: block, clickup_task_id: m.clickup_task_id, title: m.title, needs_alert: !ok, has_embedded: false, warn_source: ok ? '' : 'multimodal/zip-image-store-failed', err: ok ? '' : 'zip-inner image upload/sign failed' } };

const m = $json;
const reason = m.drop_reason || 'zip_entry_dropped';
return { json: { block: { type: 'text', order: m.order, md: '[BRAK: ' + reason + ' ' + (m.title || '') + ']' }, clickup_task_id: m.clickup_task_id, title: m.title, needs_alert: true, has_embedded: false, warn_source: m.warn_source || 'multimodal/zip-dropped', err: reason } };

const item = $input.item;
item.binary = $('Merge Extractable').item.binary;
return item;

const items = $input.all();
const out = [];
for (let z = 0; z < items.length; z++) {
  const resp = items[z].json || {};
  let parent = {};
  try { parent = $('Explode Attachments').itemMatching(z).json || {}; } catch (e) { try { parent = $('Explode Attachments').first().json || {}; } catch (e2) { parent = {}; } }
  const taskId = parent.clickup_task_id || null;
  const parentAttId = parent.att_id || 'zip';
  const parentOrder = (parent.order !== undefined && parent.order !== null) ? Number(parent.order) : 0;
  const parentTitle = parent.title || 'archive.zip';
  const entries = Array.isArray(resp.entries) ? resp.entries : null;
  if (!entries || resp.ok === false) {
    out.push({ json: { clickup_task_id: taskId, att_id: parentAttId + ':x', title: parentTitle, order: parentOrder + 0.001, route: 'drop', drop_reason: 'zip_extraction_failed', warn_source: 'multimodal/zip-extraction-failed' }, pairedItem: z });
    continue;
  }
  for (let i = 0; i < entries.length; i++) {
    const e = entries[i] || {};
    const idx = (e.index !== undefined && e.index !== null) ? Number(e.index) : i;
    const order = parentOrder + (idx + 1) / 1000;
    const attId = e.att_id || (parentAttId + ':' + idx);
    if (e.route === 'drop') {
      out.push({ json: { clickup_task_id: taskId, att_id: attId, title: e.name || parentTitle, order: order, route: 'drop', drop_reason: e.drop_reason || 'zip_entry_dropped', warn_source: e.warn_source || 'multimodal/zip-dropped' }, pairedItem: z });
      continue;
    }
    out.push({ json: { clickup_task_id: taskId, att_id: attId, title: e.name || '', ext: e.ext || '', mime: e.mime || '', order: order, source: 'zip', route: e.route, ref: e.signed_url || '', signed_url: e.signed_url || '', stored: !!e.stored, storage_path: e.storage_path || '' }, pairedItem: z });
  }
}
return out;

const item = $input.item;
if (item.binary && item.binary.data) {
  const b = item.binary.data;
  let meta = {};
  try { meta = $('Fan Manifest').item.json || {}; } catch (e) { meta = {}; }
  const raw = String(meta.title || b.fileName || 'document');
  const base = raw.split('/').pop() || 'document';
  const ext = String(meta.ext || (base.includes('.') ? base.split('.').pop() : '')).toLowerCase();
  b.fileName = base.includes('.') ? base : (ext ? base + '.' + ext : base);
  if (ext) b.fileExtension = ext;
  if (meta.mime) b.mimeType = meta.mime;
}
return item;

const m = $json || {};
let cfg = {};
try { cfg = $('Lookup File Processing Config').first().json || {}; } catch (e) { cfg = {}; }
const hasCfg = cfg && cfg.zip_max_entries != null && cfg.zip_max_file_mb != null && cfg.zip_max_total_uncompressed_mb != null;
const caps = {
  max_entries: Number(cfg.zip_max_entries) || 50,
  max_file_mb: Number(cfg.zip_max_file_mb) || 25,
  max_total_mb: Number(cfg.zip_max_total_uncompressed_mb) || 250
};
return { json: {
  clickup_task_id: m.clickup_task_id,
  att_id: m.att_id,
  title: m.title,
  order: m.order,
  url: m.url,
  task_id: m.clickup_task_id,
  attachment_id: m.att_id,
  parent_title: m.title,
  caps: caps,
  caps_source: hasCfg ? 'config' : 'default',
  only_index: (m.only_inner_index != null ? Number(m.only_inner_index) : null)
} };

const TEXT_EXT = new Set(['csv', 'txt', 'tsv', 'tab']);
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const bin = items[i].binary && items[i].binary.data;
  if (!bin) continue; // fetch failed / no binary -> let Docling + Build Text Block degrade to [BRAK]
  const fromName = bin.fileName ? String(bin.fileName).split('.').pop() : '';
  const ext = String((items[i].json && items[i].json.ext) || fromName || '').toLowerCase();
  if (!TEXT_EXT.has(ext)) continue; // pdf/docx/xlsx/img: never touch (would corrupt a zip-based office doc)
  const buf = await this.helpers.getBinaryDataBuffer(i, 'data');
  let validUtf8 = true;
  try { new TextDecoder('utf-8', { fatal: true }).decode(buf); } catch (e) { validUtf8 = false; }
  if (validUtf8) continue; // already UTF-8 (incl. pure ASCII) -> Docling reads it fine
  const text = new TextDecoder('windows-1250').decode(buf); // Polish Excel default codepage
  const utf8 = Buffer.from(text, 'utf-8');
  items[i].binary.data = await this.helpers.prepareBinaryData(utf8, bin.fileName, bin.mimeType);
  items[i].json = Object.assign({}, items[i].json, { _transcoded_from: 'windows-1250' });
}
return items;
